INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('KJZZ radio — This I-17 Willard Springs Wildlife Overpass near Flagstaff allows animals to safely cross highway', 'Radio interview', 'Nolan', 'Our bridge! ADOT is building it south of Flagstaff with money from a federal pilot program. Mostly to stop elk crashes: Game and Fish (Jeff Gagnon) collared elk starting around 2007 to find where they cross. Fences steer animals to the bridge, and plants on the bridge make it feel natural. Some crossings went from about 400 crashes a year to zero; elk take time to learn, and crashes drop about 40% a year. Even shy pronghorn use bridges.', 'https://www.kjzz.org/the-show/2026-07-23/this-i-17-willard-springs-wildlife-overpass-near-flagstaff-allows-animals-to-safely-cross-highway', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('Los Angeles Times — Wildlife crossings aren''t enough to curb roadkill hot spots, researchers say', 'News', 'Nolan', 'UC Davis: cars kill about 780 mountain lions (18%) and 44,000 mule deer a year in California. Crossings need long fences too: "just building a crossing doesn''t mean wildlife will use it." Best fence: at least 8 ft tall, fine mesh at the bottom, overhang on top. Crossings + fencing can cut big-animal crashes by more than 80% (Pew).', 'https://www.latimes.com/california/story/2026-11-10/wildlife-crossings-arent-enough-to-curb-roadkill-hot-spots-researchers-say', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('WWF — Wildlife Crossings Reduce Collisions and Save Lives', 'Article (nonprofit)', 'Nolan', 'US cars hit large animals 1–2 million times a year: $8 billion+ in costs and 200 people killed. Banff (6 bridges + 38 underpasses) cut crashes 80%. Montana Hwy 93: 42 crossings, 22,000+ animals a year, crashes down 70%+. Nepal used camera traps to prove 13 species used 4 underpasses (like our camera idea!).', 'https://www.worldwildlife.org/news/magazine/fall-2023/wildlife-crossings-help-avoid-roadway-collisions/', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('Think Wildlife Foundation — How effective are wildlife crossings?', 'Article (nonprofit)', 'Nolan', 'Banff''s 44 crossings cut big-animal crashes 80%+. Netherlands: roadkill down 96% for some species. A study of 89 crossings found more animals cross where structures are. Crossings only work if they are in the right place, kept clear, and the right size for the animal.', 'https://thinkwildlifefoundation.com/how-effective-are-wildlife-crossings/', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('Leave No Trace — Up, Under and Across: How Do Wildlife Cross a Road?', 'Article (nonprofit)', 'Nolan', 'Kinds of crossings: bridge, underpass, tunnel, culvert, canopy bridge. First US wildlife bridge: Utah, 1975. Arizona is one of the crash hot-spot states with crossings. Fits Leave No Trace Principle #6, Respect Wildlife.', 'https://lnt.org/up-under-and-across-how-do-wildlife-cross-a-road/', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('All That''s Interesting — Wildlife Crossings: 25 Stunning Animal Bridges From Around The World', 'Article (photo gallery)', 'Nolan', 'Over a million animals are killed by cars every day (estimate). Expert Ben Goldfarb: crossings + fences cut crashes "by 90 percent or so." Banff: 150,000+ animals used its crossings 1996–2016. Arizona: about 20 wildlife bridges since 2000 (page gives no source).', 'https://allthatsinteresting.com/wildlife-crossings', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('Sigma Earth — Can Wildlife Bridge Truly Make A Difference In Conserving Endangered Species?', 'Article (blog)', 'Nolan', 'Bridges + fences cut deer, bear and mountain lion roadkill by about 90%. Netherlands: 600+ green bridges. Not every animal uses them (shy or night animals may not), so each design has to fit its animals. Bridges need upkeep and checking after they''re built.', 'https://sigmaearth.com/can-wildlife-bridge-truly-make-a-difference-in-conserving-endangered-species/', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('Gokce Capital — Wildlife Crossings: 11 Things (2026) You Have to Know', 'Article (business blog)', 'Nolan', 'Banff: crashes down 80–90% (about 100 a year before, fewer than 6 now), but animals can take years to start using a crossing. A crossing costs $500,000 to $6 million; underpasses cost less. US Wildlife Crossings Pilot Program (2021): $350 million in grants over 5 years.', 'https://gokcecapital.com/wildlife-crossings/', 0);
INSERT INTO research (source, type, found_by, note, url, sample) VALUES ('ResearchGate — Twenty years of research, do animals use wildlife crossings?', 'Science paper', 'Nolan', '[unclear: the site blocked Claude from opening it. Nolan, what did you learn from this one?]', 'https://www.researchgate.net/publication/283315702_Twenty_years_of_research_do_animals_use_wildlife_crossings', 0);
INSERT INTO entries (date, who, component, phase, text, core_values, success, source) VALUES ('2026-11-14', '["Nolan"]', 'Innovation Project', 'RESEARCH', 'Nolan researched whether wildlife crossings work and found 9 sources (KJZZ, LA Times, WWF, Leave No Trace and more). Almost all say crossings cut crashes 70–96%, but only if animals actually use them, and someone has to check: in Nepal they proved it with camera traps. That is what our camera on the I-17 Willard Springs bridge would do.', '["Discovery"]', 0, 'update');
